import mpmath as mp
ctx = mp.mp
ctx.dps = 100

def brute(n_, z, q):
    if n_ == 1:
        return 2*q**(ctx.mpf(1)/4)*ctx.nsum(lambda k: (-1)**k * q**(k*(k+1)) * ctx.sin((2*k+1)*z), [0, ctx.inf], tol=ctx.eps*ctx.mpf("1e-30"))
    if n_ == 2:
        return 2*q**(ctx.mpf(1)/4)*ctx.nsum(lambda k: q**(k*(k+1)) * ctx.cos((2*k+1)*z), [0, ctx.inf], tol=ctx.eps*ctx.mpf("1e-30"))
    if n_ == 3:
        return 1 + 2*ctx.nsum(lambda k: q**(k*k) * ctx.cos(2*k*z), [1, ctx.inf], tol=ctx.eps*ctx.mpf("1e-30"))
    if n_ == 4:
        return 1 + 2*ctx.nsum(lambda k: (-q)**(k*k) * ctx.cos(2*k*z), [1, ctx.inf], tol=ctx.eps*ctx.mpf("1e-30"))

cases = [
